__STATIC_INLINE uint32_t LL_IWDG_IsReady(IWDG_TypeDef const *IWDGx)
{
  return ((READ_BIT(IWDGx->SR, IWDG_SR_PVU | IWDG_SR_RVU | IWDG_SR_WVU) == 0U) ? 1UL : 0UL);
